<template>
	<d2-container>
		<div>
			<div v-if="nowView===1">
				<div>
					<el-button type="primary" icon="el-icon-refresh" size="medium" @click="getTableData()">刷新</el-button>
					<el-button v-if="authKeys.indexOf('18')>-1" type="success" icon="el-icon-circle-plus-outline" size="medium" @click="goToAdd()">新建</el-button>
					<el-button v-if="authKeys.indexOf('20')>-1" type="danger" icon="el-icon-delete" size="medium" @click="handleDatas('删除')">删除</el-button>
					<el-button v-if="authKeys.indexOf('21')>-1" type="success" plain icon="el-icon-document-checked" size="medium"
					 @click="handleDatas('审核')">审核</el-button>
					<el-button v-if="authKeys.indexOf('22')>-1" type="danger" plain icon="el-icon-document-delete" size="medium"
					 @click="handleDatas('回滚')">回滚</el-button>

					<el-input style="margin-left:30px;width: 150px;" size="medium" placeholder="搜索素材名称" v-model="searchFilter.name"
					 clearable></el-input>
					<el-autocomplete style="margin-left:10px;width: 120px;" v-model="searchFilter.state" :fetch-suggestions="querySearch"
					 clearable placeholder="状态" size="medium"></el-autocomplete>
					<el-button style="margin-left:10px;" type="primary" icon="el-icon-search" size="medium" plain @click="handleSearch">搜索</el-button>
					<el-button type="primary" icon="el-icon-zoom-out" size="medium" plain @click="clearFilter()">清空条件</el-button>
				</div>


				<vxe-table style="margin-top: 10px;" border stripe resizable highlight-hover-row highlight-current-row align="center"
				 :height="tableHeight" :loading="loading" row-id="ID" :data="tableData" ref="xTable1" :expand-config="tableExtendConfig"
				 show-footer :footer-method="tableFooter">
					<vxe-table-column type="checkbox" width="60"></vxe-table-column>
					<vxe-table-column v-if="authKeys.indexOf('19')>-1" title="操作" width="80">
						<template v-slot="{ row }">
							<el-button type="warning" plain size="small" @click="goToEdit(row)">编辑</el-button>
						</template>
					</vxe-table-column>

					<vxe-table-column type="expand" width="60" title="展开">
						<template v-slot:content="{ row, rowIndex }">
							<ul>
								<li>
									<span>ID：</span>
									<span>{{ row.ID }}</span>
								</li>
								<li>
									<span>Name：</span>
									<span>{{ row.Name }}</span>
								</li>
								<li>
									<span>好刷吗：</span>
									<span>{{ row.Easy }}</span>
								</li>
							</ul>
						</template>
					</vxe-table-column>

					<vxe-table-column type="seq" width="60" title="序号"></vxe-table-column>
					<vxe-table-column field="ID" title="ID" :visible="false"></vxe-table-column>
					<vxe-table-column field="State" title="状态"></vxe-table-column>
					<vxe-table-column field="Name" title="素材名称"></vxe-table-column>
					<vxe-table-column field="Easy" title="好刷吗"></vxe-table-column>
					<vxe-table-column field="Address" title="地点"></vxe-table-column>
					<vxe-table-column field="Status" title="修改次数"></vxe-table-column>
					<vxe-table-column field="LastEditTime" title="最近编辑时间"></vxe-table-column>
				</vxe-table>

				<vxe-pager :loading="loading" :current-page="tablePage.currentPage" :page-size="tablePage.pageSize" :total="tablePage.totalResult"
				 :layouts="['PrevPage', 'JumpNumber', 'NextPage', 'FullJump', 'Sizes', 'Total']" @page-change="handlePageChange">
				</vxe-pager>
			</div>
			<div v-if="nowView===2">
				<WorkEdit :passID="passID" :authKeys="authKeys" @goBack="goBack"></WorkEdit>
			</div>
		</div>
	</d2-container>
</template>

<script>
	import {
		GetAuthKeys,
	} from '@api/sys.login.js'


	import WorkEdit from './WorkEdit.vue'
	import {
		GetAllWork,
		DeleteWorks,
		ApproveWorks,
		DisApproveWorks
	} from '@api/WorkInfo.js'


	export default {
		name: 'WorkInfo',
		components: {
			WorkEdit,
		},
		data() {
			return {
				nowView: 1, //当前视图：1是列表，2是编辑页面
				authKeys: [], //用户的权限数组
				tableHeight: 0, //表格高度
				tableData: [], //表内数据
				tableExtendConfig: {
					'iconOpen': 'fa fa-minus-square',
					'iconClose': 'fa fa-plus-square',
					'lazy': true,
					'loadMethod': this.tableExtendLoad
				},
				loading: false, //是否显示加载中
				tablePage: { // 分页属性---
					currentPage: 1,
					pageSize: 10,
					totalResult: 0
				},


				//搜索变量
				searchFilter: {
					name: '',
					state: ''
				},
				states: [{
					'value': '正常'
				}, {
					'value': '刚新建的'
				}, {
					'value': '已被修改'
				}, {
					'value': '即将删除'
				}],

				passID: null,
			}
		},
		created() {
			this.getAuthKeys()
		},
		mounted() {
			this.autoTableHeight()
		},
		methods: {
			//表格根据浏览器调整高度---
			autoTableHeight() {
				this.tableHeight = window.innerHeight - 238;
				window.onresize = () => {
					return (() => {
						this.tableHeight = window.innerHeight - 238;
					})();
				};
			},

			getAuthKeys() {
				GetAuthKeys({})
					.then(res => {
						this.authKeys = res.AuthKeys.split(',')
						this.getTableData()
					})
					.catch(err => {})
			},
			getTableData() {
				if (this.authKeys.indexOf('17') > -1) {
					this.loading = true
					GetAllWork({
							pageSize: this.tablePage.pageSize,
							currentPage: this.tablePage.currentPage,
							searchFilter: this.searchFilter
						})
						.then(res => {
							this.tableData = res.list
							this.tablePage.totalResult = res.totalResult
							this.loading = false
						})
						.catch(err => {
							// 异常情况
							this.loading = false
						})
				}

			},
			//换页控件
			handlePageChange({
				currentPage,
				pageSize
			}) {
				this.tablePage.currentPage = currentPage
				this.tablePage.pageSize = pageSize
				this.getTableData()
			},
			//查询按钮
			handleSearch() {
				this.tablePage.currentPage = 1 //注意要回来第一页
				this.getTableData()
			},
			//清空搜索条件
			clearFilter() {
				let obj = this.searchFilter
				for (let key in obj) {
					obj[key] = null
				}
			},

			//表扩展
			tableExtendLoad({
				row
			}) {
				let p = new Promise(resolve => {
					console.log(row)
					resolve()
				})
				//需要返回Promise对象
				return p
			},

			//表尾合计
			tableFooter({
				columns,
				data
			}) {
				let sums = []
				columns.forEach((column, columnIndex) => {
					if (columnIndex === 0) {
						sums.push('合计')
					} else {
						let sumCell = null
						switch (column.property) {
							case 'Status':
								sumCell = this.$XEUtils.sum(data, column.property)
								break
						}
						sums.push(sumCell)
					}
				})
				// 返回一个二维数组的表尾合计
				return [sums]
			},


			handleDatas(e) {
				let selectRecords = this.$refs.xTable1.getCheckboxRecords()
				let tempIDs = []
				for (let i = 0; i < selectRecords.length; i++) {
					let sr = selectRecords[i]
					tempIDs.push(sr.ID)
				}
				if (tempIDs.length > 0) {
					this.$confirm('确定要' + e + '这' + tempIDs.length + '行?', '提示', {
						confirmButtonText: '确定',
						cancelButtonText: '取消',
						type: 'warning'
					}).then(() => {
						switch (e) {
							case '删除':
								DeleteWorks({
										IDs: tempIDs.join(',')
									})
									.then(res => {
										this.getTableData()
										this.$message.success('删除成功')
									})
									.catch(err => {})
								break;
							case '审核':
								this.$message.warning('演示按钮，暂无审核效果')
								break;
							case '回滚':
								this.$message.warning('演示按钮，暂无回滚效果')
								break;
						}

					}).catch(() => {});

				} else {
					this.$message.warning('请先勾选要操作的行')
				}
			},

			deleteDatas() {
				let selectRecords = this.$refs.xTable1.getCheckboxRecords()
				console.log(selectRecords)
				let tempIDs = []
				for (let i = 0; i < selectRecords.length; i++) {
					let sr = selectRecords[i]
					tempIDs.push(sr.ID)
				}
				if (tempIDs.length > 0) {
					this.$confirm('确定要删除这' + tempIDs.length + '行?', '提示', {
						confirmButtonText: '确定',
						cancelButtonText: '取消',
						type: 'warning'
					}).then(() => {
						console.log(tempIDs.join(','))
						DeleteWorks({
								IDs: tempIDs.join(',')
							})
							.then(res => {
								this.getTableData()
								this.$message.success('删除成功')
							})
							.catch(err => {})
					}).catch(() => {});

				} else {
					this.$message.warning('请先勾选要删除的行')
				}
			},


			//智能下拉---
			querySearch(queryString, cb) {
				let values = this.states; //传入下拉列表数组
				let results = queryString ? values.filter(this.createFilter(queryString)) : values;
				// 调用 callback 返回建议列表的数据
				cb(results);
			},
			createFilter(queryString) {
				return (e) => {
					return (e.value.toLowerCase().indexOf(queryString.toLowerCase()) === 0);
				}
			},
			//智能下拉---



			goToAdd() {
				this.nowView = 2
				this.passID = ''
			},
			goToEdit(row) {
				this.nowView = 2
				this.passID = row.ID
			},
			goBack() { //子组件对外触发的返回父事件
				this.nowView = 1
				this.getTableData()
			},
		},


	}
</script>

<style scoped>
	.fn {
		background-color: #0000EE;
	}
</style>

<vue-filename-injector>
export default function (Component) {
  Component.options.__source = "src/views/pages/WorkInfo/WorkInfo.vue"
}
</vue-filename-injector>
