import request from '@/plugin/axios'
import cryptoJS from '@/libs/util.cryptoJS.js'

export function UploadPic(data) {
	return request({
		url: '/UploadPic',
		method: 'post',
		headers: {
			'Content-Type': 'multipart/form-data'
		},
		data: data
	})
}

export function UploadFile(data) {
	return request({
		url: '/UploadFile',
		method: 'post',
		headers: {
			'Content-Type': 'multipart/form-data'
		},
		data: data
	})
}
